// One rule for which photo is a product's primary image and how every photo is
// described to screen readers. Used by cards, the product page gallery, the home
// preview and the cart so they never disagree.
//
// Source of truth: the product's own `images` from the database (admin uploads /
// future storage-backed uploads). Only when a product has NO database images is the
// static photo gallery used, matched by EXACT SKU (src/data/productGallery.json,
// generated by scripts/assets/build_product_images.py from the verified photo copies).
//
// Order: database images -> `is_main` first, then `sort_order`, then stored order;
// static gallery -> the reviewed order in scripts/assets/product_image_map.json.
// Numbered photo variations are gallery views of ONE product, never inventory variants.
import staticGallery from "@/data/productGallery.json";

const FILENAME_LIKE = /\.(png|jpe?g|webp|gif|avif)$/i;

function goodAlt(text) {
  const t = (text || "").trim();
  return t && !FILENAME_LIKE.test(t) ? t : "";
}

function describe(list, name) {
  const n = list.length;
  return list.map((img, k) => ({
    src: img.src,
    srcSet: img.srcSet,
    width: img.width,
    height: img.height,
    alt: goodAlt(img.alt) || (n > 1 ? `${name} — image ${k + 1} of ${n}` : name),
  }));
}

export function staticImagesForSku(sku) {
  const entry = sku ? staticGallery.products?.[String(sku).trim()] : null;
  return entry ? entry.images : [];
}

// The admin can reorder a product's reviewed static photos (Admin -> Products -> Photos);
// the saved order arrives as product.gallery_order (list of photo URLs, first = cover).
// Photos missing from the saved order keep their reviewed position after the ordered ones;
// unknown URLs are ignored, so a stale order can never add or hide a photo.
export function orderedStatic(product) {
  const base = staticImagesForSku(product?.sku);
  const order = Array.isArray(product?.gallery_order) ? product.gallery_order : [];
  if (!order.length) return base;
  const rank = new Map(order.map((u, k) => [u, k]));
  return base
    .map((img, i) => ({ img, i }))
    .sort((a, b) => (rank.has(a.img.src) ? rank.get(a.img.src) : order.length + a.i) - (rank.has(b.img.src) ? rank.get(b.img.src) : order.length + b.i))
    .map(({ img }) => img);
}

export function productImages(product) {
  const name = product?.product_name || "Product";
  const fromDb = (product?.images || [])
    .map((img, i) => ({ img: img || {}, i }))
    .filter(({ img }) => typeof img.image_url === "string" && img.image_url.trim())
    .sort((a, b) =>
      (b.img.is_main ? 1 : 0) - (a.img.is_main ? 1 : 0) ||
      (Number(a.img.sort_order) || 0) - (Number(b.img.sort_order) || 0) ||
      a.i - b.i)
    .map(({ img }) => ({ src: img.image_url, alt: img.alt_text }));
  if (fromDb.length) return describe(fromDb, name);
  return describe(orderedStatic(product).map((img) => ({ ...img, alt: "" })), name);
}

export function primaryImage(product) {
  return productImages(product)[0] || { src: undefined, alt: product?.product_name || "" };
}
